* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  background: #f5f6f8;
  color: #222;
}

main {
  max-width: 760px;
  margin: 0 auto;
  padding: 24px 16px;
}

h1 {
  margin-top: 0;
}

.balance {
  font-size: 1.25rem;
}

.add-form,
.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-bottom: 16px;
}

input[type="text"],
input[type="number"],
input[type="date"],
select {
  padding: 6px 8px;
  border: 1px solid #bbb;
  border-radius: 4px;
  font: inherit;
}

#description {
  flex: 2 1 160px;
}

#amount,
#category,
#date {
  flex: 1 1 120px;
}

button {
  padding: 6px 12px;
  border: none;
  border-radius: 4px;
  background: #2b6cb0;
  color: #fff;
  font: inherit;
  cursor: pointer;
}

button:hover {
  background: #2c5282;
}

button.delete {
  background: #c53030;
  padding: 3px 8px;
  font-size: 0.85rem;
}

button.delete:hover {
  background: #9b2c2c;
}

.toolbar label {
  display: flex;
  align-items: center;
  gap: 6px;
}

table {
  width: 100%;
  border-collapse: collapse;
  background: #fff;
  margin-bottom: 24px;
}

th,
td {
  padding: 8px;
  border-bottom: 1px solid #e2e2e2;
  text-align: left;
}

td:nth-child(3),
th:nth-child(3) {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

canvas {
  display: block;
  max-width: 100%;
  height: auto;
  background: #fff;
  border: 1px solid #e2e2e2;
  border-radius: 4px;
}

